 [STAThread]static int Main(){try{Directory.CreateDirectory(Output);_=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};SynchronizationContext.SetSynchronizationContext(new System.Windows.Threading.DispatcherSynchronizationContext(Application.Current.Dispatcher));Run();AllTransportChecks.Run(Check,Output);HostChecks.Run(Check,Output);ParentLifecycleChecks.Run(Check,Output);File.WriteAllText(Path.Combine(Output,"checks.json"),JsonSerializer.Serialize(new{checks,passed,scope="actual configuration selectors, typed document, GraphExecutor and MainWindow self-run; candidate index adapter",originalDesktop=false},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"PASS {checks} CameraMapping index checks");return 0;}catch(Exception error){File.WriteAllText(Path.Combine(Output,"checks-failed.json"),JsonSerializer.Serialize(new{checks,passed,failure=error.ToString()},new JsonSerializerOptions{WriteIndented=true}));Console.Error.WriteLine(error);return 1;}}
 static IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(root,i)))yield return child;}
 static IEnumerable<ConfigurationSubscriptionTreeNode> Entries(ItemsControl control)=>control.Items.OfType<TreeViewItem>().SelectMany(i=>new[]{(ConfigurationSubscriptionTreeNode)i.Tag}.Concat(Entries(i)));
