  var node=Flow().Nodes.Single(n=>n.Id==target);var notices=new Notices();var context=new ToolEditorContext(node,Output,_=>{},_=>throw new InvalidOperationException("Test does not execute through editor button")){ConfigurationSubscriptions=service,ConfigurationNotifications=notices};
