  ToolConfigurationSubscriptionSelector Selector(string side,int group,string suffix="")=>Walk(window).OfType<ToolConfigurationSubscriptionSelector>().Single(c=>ReferenceEquals(typeof(ToolConfigurationSubscriptionSelector).GetField("node",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.GetValue(c),Child(side,group,suffix)));
