  Compare(0,"literal0");
  foreach(string side in new[]{"Object","Target"}){var selector=Selector(side,2);selector.OpenIndex();Pump();var entry=Entries(selector.Tree).Single(e=>e.Binding?.Reference is ConfigurationOutputReference output&&output.NodeId==source&&output.PortId=="Index");Check(selector.Select(entry),"actual integer index popup selects "+side);}
  Check(Flow().Configuration.Subscriptions.Where(b=>b.Target.EndsWith('2')).All(b=>b.Source.ArrayIndex?.IndexSource?.Port=="Index"),"dynamic identity saved on group2 leaves");
  producer.Index=1;Compare(1,"dynamic1");producer.Index=0;Compare(0,"dynamic0");producer.Index=null;Compare(0,"missing dynamic falls back zero");producer.Index=1;Compare(1,"recovered dynamic1 has no previous read cache");
  var implicitFlow=Flow() with{ExecutionLinks=null};Check(GraphValidator.Validate(implicitFlow,registry).IsValid,"legacy implicit DAG accepts same producer for value and dynamic index across many leaves");using(var implicitScope=new ModuleExecutionScope()){var implicitRun=new GraphExecutor(registry).RunAsync(implicitFlow,Output,scope:implicitScope).GetAwaiter().GetResult();Check(implicitRun.Nodes.Single(n=>n.NodeId==target).Status==NodeRunStatus.Success,"legacy implicit DAG executes duplicate List edges with matching indegrees");}
  string path=Path.Combine(Output,"indexed.solution.json");document.Save(path);var reloaded=new GraphEditorDocument(registry);reloaded.Load(path);Check(reloaded.CurrentProcedure.Configuration.Subscriptions.SequenceEqual(Flow().Configuration.Subscriptions),"save/load preserves typed literal and integer references");
  var before=Flow().Configuration.Subscriptions.ToArray();Check(Selector("Object",2,"X").SetIndex(ConfigurationSubscriptionIndex.At(0)),"single X selector override");var parent=service.Read(Destination("Object",2));Check(!parent.ReadOnly&&parent.Binding==Binding("Object",2,ConfigurationSubscriptionIndex.At(0)),"same POINT source with differing X/Y index remains editable and shows X first nonAll index");Check(Flow().Configuration.Subscriptions.Single(b=>b.Target=="ObjectPointY2").Source.ArrayIndex?.IndexSource?.Port=="Index","reading combined parent never rewrites Y dynamic index");document.Undo();Check(Flow().Configuration.Subscriptions.SequenceEqual(before),"Undo restores dynamic index identity");
  Check(Selector("Object",2,"X").SetIndex(ConfigurationSubscriptionIndex.All),"clear X selector to All");parent=service.Read(Destination("Object",2));Check(!parent.ReadOnly&&parent.Binding==Binding("Object",2,ConfigurationSubscriptionIndex.From(new ConfigurationOutputReference(procedure,source,"Index","int"))),"X All falls through to Y nonAll index in source Children order");document.Undo();
  var mixed=new ConfigurationSubscriptionBinding(new ConfigurationOutputReference(procedure,source,"Object1.X","float"),ConfigurationSubscriptionIndex.At(0));Check(Selector("Object",2,"X").Bind(mixed),"change X to another POINT source");var tuple=service.Read(Destination("Object",2));string sourceName=Flow().Nodes.Single(n=>n.Id==source).Name;Check(tuple.ReadOnly&&tuple.DisplayText=="("+sourceName+".Object1.X,"+sourceName+".Object2.Y)","genuinely different POINT parents show readonly source-only tuple without leaf indices");
  Check(service.Bind(new(ConfigurationSubscriptionDomain.InputIo,"ObjectPointY2","float"),null).Status==ConfigurationSubscriptionStatus.Available,"clear only Y for partial tuple");tuple=service.Read(Destination("Object",2));Check(tuple.ReadOnly&&tuple.DisplayText=="("+sourceName+".Object1.X, )","partial tuple missing Y is one blank source slot");document.Undo();
  Check(Selector("Object",2,"X").Bind(new(new ConfigurationConstantReference("float","2.5"),ConfigurationSubscriptionIndex.All)),"constant leaf for tuple UniqueName");tuple=service.Read(Destination("Object",2));Check(tuple.ReadOnly&&tuple.DisplayText=="(2.5,"+sourceName+".Object2.Y)","constant source tuple uses raw constant caption and no index suffix");document.Undo();document.Undo();
  var swappedX=new ConfigurationSubscriptionBinding(new ConfigurationOutputReference(procedure,source,"Object2.Y","float"),ConfigurationSubscriptionIndex.At(0));var swappedY=new ConfigurationSubscriptionBinding(new ConfigurationOutputReference(procedure,source,"Object2.X","float"),ConfigurationSubscriptionIndex.At(1));Check(Selector("Object",2,"X").Bind(swappedX)&&Selector("Object",2,"Y").Bind(swappedY),"swap distinct X/Y sources within same POINT parent");parent=service.Read(Destination("Object",2));Check(!parent.ReadOnly&&parent.Binding==Binding("Object",2,ConfigurationSubscriptionIndex.At(0)),"native complete distinct same-parent reconstruction does not require X/Y position identity");document.Undo();document.Undo();
  Check(Selector("Object",2,"Y").Bind(new(new ConfigurationOutputReference(procedure,source,"Object2.X","float"),ConfigurationSubscriptionIndex.At(1))),"duplicate same published X leaf in both slots");tuple=service.Read(Destination("Object",2));Check(tuple.ReadOnly&&tuple.DisplayText=="("+sourceName+".Object2.X,"+sourceName+".Object2.X)","duplicate leaf fails distinct-count gate and stays readonly tuple");document.Undo();
  Check(service.Bind(Destination("Object",2),null).Status==ConfigurationSubscriptionStatus.Available,"clear both source leaves");parent=service.Read(Destination("Object",2));Check(parent.Binding is null&&!parent.ReadOnly&&string.IsNullOrEmpty(parent.DisplayText),"all empty POINT source shows editable empty without a tuple");document.Undo();
  Selector("Object",2).Read();Check(Selector("Object",2).SetIndex(ConfigurationSubscriptionIndex.At(1)),"explicit combination index write");Check(Flow().Configuration.Subscriptions.Where(b=>b.Target is "ObjectPointX2" or "ObjectPointY2").All(b=>b.Source.ArrayIndex?.LiteralText=="1"),"only explicit combination write synchronizes both leaf indices");document.Undo();
  var sourceDefinition=System.Xml.Linq.XDocument.Load("D:/Program Files/VisionMaster4.4.0/Applications/Module(sp)/x64/Calibration/IMVSCameraMapModu/IMVSCameraMapModu.xml");foreach(var alias in plugin.PointInputAliases){var combination=sourceDefinition.Descendants("Combination").Single(e=>(string?)e.Attribute("Name")==alias.Combination);Check(combination.Descendants("Filter").Select(e=>(string?)e.Attribute("Name")).SequenceEqual(new[]{alias.X,alias.Y}),"original resource Children order is X then Y "+alias.Combination);}
  configuration.State.CommitUser("InputWay","1");configuration.State.CommitUser("InputWay","0");Pump();
  var leaf=Selector("Object",1,"X");Check(leaf.SetIndex(ConfigurationSubscriptionIndex.At(9)),"positive out of range persisted, not pre-clamped");var failure=Run();Check(failure.NativeErrorCode==0xe0000001&&failure.ErrorCode!="SubscriptionUnavailable","positive out of range wrapper Count=0 versus successful Count=1 reaches module count mismatch");document.Undo();
  foreach(string side in new[]{"Object","Target"})for(int group=1;group<=2;group++){var selector=Selector(side,group);selector.Read();var text=service.Read(Destination(side,group)).DisplayText!;int bracket=text.LastIndexOf('[');Check(selector.CommitConstant(text[..bracket]+"[-1]"),"UI signed literal accepted "+side+group);}
  failure=Run();Check(failure.NativeErrorCode==0xe0000309,"all negative selectors produce count0 and native no-points branch");
  foreach(string side in new[]{"Object","Target"})for(int group=1;group<=2;group++)Check(service.Bind(Destination(side,group),Binding(side,group,ConfigurationSubscriptionIndex.At(group==1?0:1))).Status==ConfigurationSubscriptionStatus.Available,"restore finite selected pairs");
  foreach(string raw in new[]{"1.5",".5","-.5"}){
   foreach(string side in new[]{"Object","Target"}){Check(service.Bind(Destination(side,2),Binding(side,2,ConfigurationSubscriptionIndex.At(1))).Status==ConfigurationSubscriptionStatus.Available,"seed literal1 before dot path "+raw+side);var selector=Selector(side,2);selector.Read();var text=service.Read(Destination(side,2)).DisplayText!;int beforeNotice=notices.Shown.Count;Check(!selector.CommitConstant(text[..text.LastIndexOf('[')]+"["+raw+"]"),"dot input reports failed path rather than typed literal success "+raw+side);Check(notices.Shown.Count==beforeNotice+1&&notices.Shown[^1].Kind==ConfigurationNotificationKind.Warning&&notices.Shown[^1].Message=="订阅失败","source warning once for unresolved index path "+raw+side);Check(service.Read(Destination(side,2)).Binding==Binding(side,2,ConfigurationSubscriptionIndex.All),"failed index lookup preserves source and applies All to both leaves "+raw+side);}
   Compare(null,"unresolved dot path applies All "+raw);
  }
  foreach(string side in new[]{"Object","Target"}){var selector=Selector(side,2);selector.Read();var text=service.Read(Destination(side,2)).DisplayText!;Check(selector.CommitConstant(text[..text.LastIndexOf('[')]+"[-]"),"standalone minus is source numeric literal "+side);}
  Check(Flow().Configuration.Subscriptions.Where(b=>b.Target.EndsWith('2')).All(b=>b.Source.ArrayIndex?.LiteralText=="-"),"standalone minus raw text preserved in real document");Compare(0,"standalone minus atoi zero");
  using(var injectedScope=new ModuleExecutionScope()){var injected=new Reader();injectedScope.RegisterService<IToolNumericInputReader>(injected);var result=new GraphExecutor(registry).RunAsync(Flow(),Output,scope:injectedScope).GetAwaiter().GetResult().Nodes.Single(n=>n.NodeId==target);Check(injected.Calls>0&&result.NativeErrorCode==0xe0000309,"scope numeric reader has priority over graph deferred reader");}
  var literal=JsonSerializer.Deserialize<WorkflowValueReference>("{\"Kind\":2,\"Id\":\"source\",\"Port\":\"Out\"}")!;Check(literal.ArrayIndex is null,"legacy three-field JSON retains All");
  Check(service.Bind(Destination("Object",2),Binding("Object",2,ConfigurationSubscriptionIndex.From(new ConfigurationOutputReference(procedure,source,"Index","int")))).Status==ConfigurationSubscriptionStatus.Available,"restore dynamic reference for lifecycle checks");
  var config=Flow().Configuration;var remapped=config.RemapNodes(new Dictionary<string,string>{{source,"new-source"},{target,"new-target"}});Check(remapped.Subscriptions.Where(b=>b.Source.ArrayIndex?.IndexSource is not null).All(b=>b.Source.Id=="new-source"&&b.Source.ArrayIndex!.IndexSource!.Id=="new-source"),"copy remaps both value and index producer identities");Check(config.RemoveNodes(new HashSet<string>{source}).Subscriptions.Count==0,"producer deletion removes selected input references");
  var invalid=Flow() with{Configuration=config with{Subscriptions=config.Subscriptions.Select((b,i)=>i==0?b with{Source=b.Source with{ArrayIndex=new(IndexSource:new(WorkflowSourceKind.NodeOutput,source,"Object1"))}}:b).ToArray()}};Check(!GraphValidator.Validate(invalid,registry).IsValid,"typed POINT index source rejected instead of reading numeric caption");
  var directInputs=new Dictionary<string,PortValue>{{"X",PortValue.Numbers([2,4])}};
  ModuleNumericInputReadResult? Primitive(string literal)=>new WorkflowNumericInputRead(directInputs,new Dictionary<string,WorkflowArrayIndex?>{{"X",new(literal)}},_=>throw new InvalidDataException()).Read("X",0);
  Check(Primitive("1")==new ModuleNumericInputReadResult(0,1,4),"primitive indexed success Count1");Check(Primitive("9")==new ModuleNumericInputReadResult(0xe0000014,0,0),"primitive positive bounds publishes wrapper Count0, not leaf count");Check(Primitive("-1")==new ModuleNumericInputReadResult(0xe0000014,0,0),"primitive negative count0");
  var firstGroupOnly=Flow() with{Nodes=Flow().Nodes.Select(n=>n.Id==target?n with{Parameters=n.Parameters.ToDictionary(v=>v.Key,v=>v.Key=="Data2"?JsonSerializer.SerializeToElement("Data2#0"):v.Value.Clone())}:n).ToArray(),Configuration=Flow().Configuration with{Subscriptions=Flow().Configuration.Subscriptions.Select(b=>b.Target.EndsWith('1')?b with{Source=b.Source with{ArrayIndex=b.Target=="TargetPointX1"?new("9"):null}}:b).ToArray()}};
  using(var correctedCountScope=new ModuleExecutionScope()){
   var corrected=new GraphExecutor(registry).RunAsync(firstGroupOnly,Output,scope:correctedCountScope).GetAwaiter().GetResult().Nodes.Single(n=>n.NodeId==target);
   Check(corrected.NativeErrorCode==0xe0000001,"CM02 invalid positive TX wrapper Count0 mismatches All TY count2 before group exclusion");
   var allBad=firstGroupOnly with{Configuration=firstGroupOnly.Configuration with{Subscriptions=firstGroupOnly.Configuration.Subscriptions.Select(b=>b.Target.EndsWith('1')?b with{Source=b.Source with{ArrayIndex=new("9")}}:b).ToArray()}};
   var excluded=new GraphExecutor(registry).RunAsync(allBad,Output,scope:correctedCountScope).GetAwaiter().GetResult().Nodes.Single(n=>n.NodeId==target);
