  }
  foreach(var item in new[]{("-",0),("-.5",0),(".5",0),("1.5",1),("-1.5",-1)}){Check(WorkflowArrayIndex.ParseLiteral(item.Item1)==item.Item2,"exact source numeric recognizer and bounded atoi domain "+item.Item1);Check(ConfigurationSubscriptionIndex.At(item.Item1).LiteralText==item.Item1,"API numeric literal retains raw text "+item.Item1);}
  foreach(string invalidText in new[]{"1.","1.2.3","--1","1-2","+1",""," "}){bool rejected=false;try{_=WorkflowArrayIndex.ParseLiteral(invalidText);}catch(FormatException){rejected=true;}Check(rejected,"source four-regex rejects "+JsonSerializer.Serialize(invalidText));}
  bool overflow=false;try{_=WorkflowArrayIndex.ParseLiteral("2147483648");}catch(OverflowException){overflow=true;}Check(overflow,"int32 overflow remains explicit independent managed boundary");
