 sealed class Producer:IModule {
  public int? Index=1;
  public ModuleDescriptor Descriptor{get;}=new("camera-index-source","1","Index source",[],new[]{"Object1","Object2","Target1","Target2"}.Select(n=>new PortDescriptor(n,DataKind.Point){Cardinality=ValueCardinality.Array}).Append(new("Index",DataKind.Integer,false)).ToArray(),[]);
  public Point2[] Points(string side,int group)=>side=="Object"?group==1?[new(0,0),new(9,2)]:[new(10,3),new(13,11)]:group==1?[new(7,-2),new(25,2)]:[new(27,4),new(50,30)];
  public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext context,CancellationToken token){var values=new Dictionary<string,PortValue>();foreach(string side in new[]{"Object","Target"})for(int group=1;group<=2;group++)values[side+group]=PortValue.PointArray(Points(side,group));if(Index is {} index)values["Index"]=PortValue.Integer(index);return ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,values));}
 }
 sealed class Reader:IToolNumericInputReader{public int Calls;public ToolNumericInputReadResult Read(ModuleExecutionContext context,string inputName,int index){Calls++;return new(0xe0000314,0,0);}}
 sealed class Notices:IToolConfigurationNotificationService{public readonly List<ConfigurationNotification> Shown=[];public ConfigurationNotificationResult Notify(Window? owner,ConfigurationNotification notification){Shown.Add(notification);return new(ConfigurationNotificationStatus.Displayed);}}
